"""Single-camera, single-frame walk-up experience page."""

HTML = r'''<!doctype html>
<html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>掌纹通行体验</title><style>
*{box-sizing:border-box}body{margin:0;background:#101b27;color:#f4f8fc;font:18px system-ui,sans-serif}header{display:flex;justify-content:space-between;align-items:center;padding:20px 4vw}header a{color:#b8d7ef}main{max-width:1200px;margin:auto;padding:10px 4vw 30px;display:grid;grid-template-columns:1.4fr 1fr;gap:28px}.preview{position:relative;background:#050a10;border-radius:22px;overflow:hidden;aspect-ratio:16/9}.preview img{width:100%;height:100%;object-fit:contain}.guide{position:absolute;border:2px dashed #a5d8fa88;border-radius:35%;inset:12% 27%;pointer-events:none}.panel{display:flex;flex-direction:column;justify-content:center}#symbol{font-size:64px;color:#8dc8f3}h1{font-size:42px;margin:12px 0}#hint{font-size:21px;line-height:1.6;min-height:68px}.muted{font-size:14px;color:#abc0d3;line-height:1.7}button{font:inherit;border:1px solid #5e809e;border-radius:12px;padding:10px 22px;color:white;background:#213c54;cursor:pointer}.success #symbol,.success h1{color:#68e1b5}.retry #symbol,.retry h1{color:#ffd28b}#recent{font-size:14px;line-height:1.7;white-space:pre-wrap}.label{font-size:13px;letter-spacing:2px;color:#95b6d0}.timing{font-size:14px;line-height:1.8;color:#c2d4e4;min-height:65px}@media(max-width:800px){main{grid-template-columns:1fr}h1{font-size:32px}.panel{text-align:center}header{font-size:14px}}
</style></head><body><header><span>PALM PASS · 本地体验测试</span><a href="/demo?mode=gate">录入 / 管理手掌 →</a></header>
<main><section><div class="preview"><img id="live" alt="摄像头实时预览"><div class="guide"></div></div><p id="camera" class="muted">正在连接相机</p><p class="muted">单摄像头 · 单帧识别 · 体验测试<br>这是模拟通行体验。识别准确率、活体防伪及真实设备通行能力仍待验证。</p><div id="recent" aria-label="最近测试结果"></div></section>
<section class="panel" id="panel"><div class="label">放掌 · 识别 · 移开</div><div id="symbol">◎</div><h1 id="title">请放置手掌</h1><p id="hint" role="status" aria-live="polite">手心朝向镜头，完整进入画面，稍作停留。</p><p id="timing" class="timing"></p><p id="users" class="muted">正在读取录入信息</p><div><button id="pause">暂停识别</button></div></section></main>
<script>
const $=id=>document.getElementById(id);
let paused=false,busy=false,armed=true,emptySince=null,userCount=null,needsCount=0,previewURL=null,retryFailures=0,retryNotBefore=0,recognitionEpoch=0;
const history=[];
function show(title,hint,kind='',symbol='◎'){$('title').textContent=title;$('hint').textContent=hint;$('panel').className='panel '+kind;$('symbol').textContent=symbol;}
async function request(url,options={},timeout=2500){const controller=new AbortController();const timer=setTimeout(()=>controller.abort(),timeout);try{const r=await fetch(url,{cache:'no-store',...options,signal:controller.signal});if(!r.ok)throw Error('HTTP '+r.status);return await r.json();}finally{clearTimeout(timer);}}
async function users(){try{const d=await request('/api/demo/users');userCount=d.users.filter(u=>!u.needs_reenrollment).length;needsCount=d.users.filter(u=>u.needs_reenrollment).length;$('users').textContent=`已录入 ${userCount} 只手 · 左右手各自录入`+(needsCount?` · ${needsCount} 只手的资料需要检查或更新`:'');}catch(e){$('users').textContent=userCount===null?'录入信息暂不可用':`录入信息暂不可用 · 上次读取 ${userCount} 只手`; }setTimeout(users,5000);}
function decodePreview(url){return new Promise((resolve,reject)=>{const img=new Image();const finish=error=>{clearTimeout(timer);img.onload=null;img.onerror=null;error?reject(error):resolve()};const timer=setTimeout(()=>finish(Error('预览图解码超时')),2500);img.onload=()=>finish();img.onerror=()=>finish(Error('预览图解码失败'));img.src=url;});}
async function preview(){let next;try{const r=await fetch('/debug/processed.jpg?t='+Date.now(),{cache:'no-store',signal:AbortSignal.timeout(2500)});if(!r.ok)throw Error();next=URL.createObjectURL(await r.blob());await decodePreview(next);$('live').src=next;if(previewURL)URL.revokeObjectURL(previewURL);previewURL=next;next=null;}catch(e){$('live').removeAttribute('src');}finally{if(next)URL.revokeObjectURL(next);setTimeout(preview,150);}}
async function identify(){const epoch=recognitionEpoch;busy=true;armed=false;emptySince=null;$('timing').textContent='';show('正在识别','保持手掌稳定，正在采集并识别一帧。');const started=performance.now();try{const d=await request('/api/gate/identify',{method:'POST',headers:{'Content-Type':'application/json'},body:'{}'},20000);if(epoch!==recognitionEpoch)return;const elapsed=performance.now()-started;const t=d.timing_ms||{};let message;if(d.status==='MATCH'){retryFailures=0;retryNotBefore=0;message=`模拟通过 · ${d.display_name}`;show('模拟通过',`${d.display_name}，请移开手掌。`,'success','✓');}else if(d.status==='UNKNOWN'){retryFailures=0;retryNotBefore=0;if(d.reason==='NO_ENROLLED_USERS'){message='没有可用录入资料';show('请检查录入资料','当前没有可用于识别的录入资料，请进入录入管理检查；移开手掌后可重试。','retry','!');}else{message='未识别到已录入手掌';show('未识别','请移开手掌后重试，首次使用请先录入。','retry','○');}}else{message='需要重试';if(['GALLERY_INCOMPATIBLE_TEMPLATES','INCOMPATIBLE_TEMPLATES'].includes(d.reason)){message='录入资料需要更新';show('请更新录入资料','请进入录入管理，用原编号重新录入；已有余额保留。','retry','!');}else if(['GALLERY_INCOMPLETE_TEMPLATES','GALLERY_INVALID_TEMPLATES','GALLERY_ACCOUNT_MISMATCH'].includes(d.reason)){message='录入资料需要检查';show('请检查录入资料','录入资料不完整或与账户不一致，请进入录入管理检查。','retry','!');}else if(d.reason==='GALLERY_CHANGED_DURING_QUERY'){message='录入资料正在变化';show('录入资料正在变化','请等待资料更新完成，移开手掌后重试。','retry','↻');}else if(['NO_HAND','ROI_UNSTABLE','ROI_NOT_READY','ROI_GEOMETRY_INVALID','CAPTURE_TIMEOUT','INSUFFICIENT_QUALITY_FRAMES','CAMERA_BUSY','CAMERA_UNAVAILABLE'].includes(d.reason)){armed=true;retryFailures++;retryNotBefore=performance.now()+Math.min(1000*2**Math.min(retryFailures-1,3),8000);show('请调整手掌','掌区恢复稳定后会自动继续。','retry','↻');}else show('请重试','请移开手掌，调整距离和姿态后再试。','retry','↻');}$('timing').textContent=`本次请求 ${(elapsed/1000).toFixed(2)} 秒`+(Number.isFinite(t.capture_and_extract)?` · 采集与特征 ${(t.capture_and_extract/1000).toFixed(2)} 秒`:'')+(Number.isFinite(t.gallery)?` · 图库比对 ${(t.gallery/1000).toFixed(2)} 秒`:'');history.unshift(`${new Date().toLocaleTimeString()}  ${message}  ${(elapsed/1000).toFixed(2)}s`);$('recent').textContent=history.slice(0,6).join('\n');}catch(e){if(epoch===recognitionEpoch)show('连接或处理异常','请移开手掌后重试。','retry','!');}finally{busy=false;}}
async function poll(){try{const d=await request('/api/status?t='+Date.now());const state=d.demo_quality_status??d.quality_status;const count=Number(d.demo_quality_consecutive_frames??d.quality_consecutive_frames??0);const required=Number(d.demo_quality_required_frames??d.quality_required_frames??5);const fresh=d.camera_ready&&d.roi_status_fresh===true;$('camera').textContent=fresh?'相机已连接 · 实时掌区检测':'相机或掌区状态暂不可用';if(!busy&&!document.hidden){if(paused){show('识别已暂停','点击继续后开始下一轮。');}else if(userCount===null){show('录入信息暂不可用','正在等待录入信息恢复。','retry');}else if(userCount===0){if(needsCount)show('请检查录入资料','进入录入管理，用原编号检查并更新已有资料。','retry','!');else show('请先录入手掌','点击右上角录入入口，自动采集并保存五张。');}else if(!fresh){emptySince=null;show('等待相机','正在等待实时画面与检测状态恢复。','retry');}else if(!armed){if(state==='NO_HAND'){emptySince??=performance.now();if(performance.now()-emptySince>=700){armed=true;emptySince=null;$('timing').textContent='';show('请放置手掌','手心朝向镜头，完整进入画面，稍作停留。');}}else emptySince=null;}else if(state==='READY'&&count>=required){if(performance.now()>=retryNotBefore)void identify();else show('请调整手掌','正在等待掌区稳定后自动重试。','retry','↻');}else if(state==='NO_HAND'){retryFailures=0;retryNotBefore=0;show('请放置手掌','手心朝向镜头，完整进入画面，稍作停留。');}else{show('请稳住手掌','掌心朝向镜头，稍微调整距离，等待清晰稳定的画面。');}}}catch(e){emptySince=null;if(!busy)show('连接暂不可用','等待服务恢复。','retry');}finally{setTimeout(poll,300);}}
$('pause').onclick=()=>{recognitionEpoch++;paused=!paused;$('pause').textContent=paused?'继续识别':'暂停识别';if(paused){show('识别已暂停','点击继续后开始下一轮。');}else{armed=false;emptySince=null;show('请移开手掌','移开后重新放掌，开始下一轮。');}};
users();preview();poll();
</script></body></html>'''
